            ['id' => '1', 'title' => 'About Oxford', 'slug' => 'about', 'details' => '<p data-mce-style=\"text-align: justify;\"><strong>A Special Set-Up</strong></p>\r\n\r\n<p data-mce-style=\"text-align: justify;\">The Oxford English Centre was&nbsp;<strong>established in 2011&nbsp;</strong>as a private English Language Teaching (ELT) Centre and one of the very few centers, if not the only in Gaza, targeting adult Language Learners. It is a proud local ELT Service -Provider accredited by The Palestinian Ministry of Education and adopts the most modern ELT methodologies including The Communicative Learner-Centered and The Task-Based Approaches allowing for more learner autonomy. The Centre is led by an experienced and socially- responsible team of young highly-qualified Palestinian administrators and academics.</p>\r\n\r\n<p data-mce-style=\"text-align: justify;\"><strong>A Convenient Location and Welcoming Atmosphere</strong></p>\r\n\r\n<p data-mce-style=\"text-align: justify;\">Oxford is located in a convenient location in Ansar Square within a walking distance from Gaza universities and covers an area of 350 m2 on the third floor of Mushtaha Tower(6). The facility has six highly equipped and air-conditioned training rooms with a maximum capacity of 15 participants per room, along with a reception and a spacious veranda devoted for clients&#39; tea breaks overlooking Al- Katibah Park, not to mention the Ladies&#39; and Gents&#39; toilets and the small kitchen where clients are welcome to serve themselves hot drinks. In addition, Oxford has a separate quite administration room, yet Top Management is approachable allowing clients to feel supported in a friendly way. In a second separate flat located on the same floor, two highly-equipped spacious halls are devoted for Conferences and Training constituting together a maximum capacity of 70 trainees and participants . The entire place features Georgian and late Victorian interior design, the thing which Oxford exclusively offers as an added value to its clients in order to the best academic atmosphere integrated with a cultural experience Gazans cannot have elsewhere in their besieged Strip.</p>\r\n\r\n<p data-mce-style=\"text-align: justify;\"><strong>Our Mission</strong></p>\r\n\r\n<p data-mce-style=\"text-align: justify;\">Our mission is to inspire our students to achieve their potential and their personal goals in language learning in a supportive environment.</p>\r\n\r\n<p data-mce-style=\"text-align: justify;\"><strong>Our Ethos</strong></p>\r\n\r\n<p data-mce-style=\"text-align: justify;\">A high quality of student welfare is central to our ethos, along with a high standard of teaching and learning.</p>\r\n\r\n<p data-mce-style=\"text-align: justify;\"><strong>Our aims include:</strong></p>\r\n\r\n<ol>\r\n	<li>\r\n	<p>being a centre where the well-being of everyone is the prime concern of each member of our community.</p>\r\n	</li>\r\n	<li>supporting a learning community in which all students can realize their full potential, whatever that may</li>\r\n	<li>providing a safe, stimulating and enriching environment where everyone is able to enjoy his/her learning</li>\r\n	<li>encouraging students to be active members of their community through a range of activities, trips and</li>\r\n	<li>promoting regular attendance and good behaviour as pre-conditions for maintaining high standards of</li>\r\n	<li>encouraging tolerance and understanding between all members of our</li>\r\n</ol>', 'image' => 'uploads/image/image_1564390950.jpg', 'banner' => '/uploads/photos/shares/5d3eb389d9cd4.jpg', 'url' => 'https://www.youtube.com/watch?v=9slg-jDuqYM', 'tags' => 'oxford ,gaza,ielts,test,score,best,uk,scholarships', 'status' => '1', 'age' => null, 'level' => null, 'weeks' => null, 'hours' => null, 'mock' => null, 'duration' => null, 'class_size' => null, 'fees' => null, 'price' => null, 'start' => null, 'days' => null, 'time' => null, 'created_at' => '2017-08-15 15:45:27', 'updated_at' => '2019-07-29 21:44:23', 'deleted_at' => null, ],
            ['id' => '2', 'title' => 'Oxford Promise', 'slug' => 'promise', 'details' => '<p style=\"text-align:justify; margin:0cm 0cm 10pt\"><span style=\"font-size:11pt\"><span style=\"unicode-bidi:embed\"><span style=\"line-height:115%\"><span style=\"font-family:Calibri,sans-serif\"><b>The Oxford promise and what it means to you</b></span></span></span></span></p>\r\n\r\n<p style=\"text-align:justify; margin:0cm 0cm 10pt\"><span style=\"font-size:11pt\"><span style=\"unicode-bidi:embed\"><span style=\"line-height:115%\"><span style=\"font-family:Calibri,sans-serif\">Our unique Oxford Promise means that, as long as you follow your personalised learning programme and take the three steps outlined below, we promise that your English will improve.</span></span></span></span></p>\r\n\r\n<p style=\"text-align:justify; margin:0cm 0cm 10pt\"><span style=\"font-size:11pt\"><span style=\"unicode-bidi:embed\"><span style=\"line-height:115%\"><span style=\"font-family:Calibri,sans-serif\"><b>Attendance</b></span></span></span></span></p>\r\n\r\n<p style=\"text-align:justify; margin:0cm 0cm 10pt\"><span style=\"font-size:11pt\"><span style=\"unicode-bidi:embed\"><span style=\"line-height:115%\"><span style=\"font-family:Calibri,sans-serif\">Class attendance is an individual student responsibility. Attend 96% of your English language classes.</span></span></span></span></p>\r\n\r\n<p style=\"text-align:justify; margin:0cm 0cm 10pt\"><span style=\"font-size:11pt\"><span style=\"unicode-bidi:embed\"><span style=\"line-height:115%\"><span style=\"font-family:Calibri,sans-serif\"><b>Homework</b></span></span></span></span></p>\r\n\r\n<p style=\"text-align:justify; margin:0cm 0cm 10pt\"><span style=\"font-size:11pt\"><span style=\"unicode-bidi:embed\"><span style=\"line-height:115%\"><span style=\"font-family:Calibri,sans-serif\">Compete at least three homework assignments weekly with an average score of 9/10.</span></span></span></span></p>\r\n\r\n<p style=\"text-align:justify; margin:0cm 0cm 10pt\"><span style=\"font-size:11pt\"><span style=\"unicode-bidi:embed\"><span style=\"line-height:115%\"><span style=\"font-family:Calibri,sans-serif\"><b>Participation</b></span></span></span></span></p>\r\n\r\n<p style=\"text-align:justify; margin:0cm 0cm 10pt\"><span style=\"font-size:11pt\"><span style=\"unicode-bidi:embed\"><span style=\"line-height:115%\"><span style=\"font-family:Calibri,sans-serif\">Actively participate in lessons with an average score of 9/10 for participation and motivation.</span></span></span></span></p>\r\n\r\n<p style=\"text-align:justify; margin:0cm 0cm 10pt\"><span style=\"font-size:11pt\"><span style=\"unicode-bidi:embed\"><span style=\"line-height:115%\"><span style=\"font-family:Calibri,sans-serif\"><b>Progress Planner</b></span></span></span></span></p>\r\n\r\n<p style=\"text-align:justify; margin:0cm 0cm 10pt\"><span style=\"font-size:11pt\"><span style=\"unicode-bidi:embed\"><span style=\"line-height:115%\"><span style=\"font-family:Calibri,sans-serif\">Our Progress Planner below will help you plan your route to fluency, and be confident that your success is guaranteed. Get an idea of how many lessons you need to get to your target level by simply counting the weeks.</span></span></span></span></p>\r\n\r\n<p style=\"text-align:justify; margin:0cm 0cm 10pt\"><span style=\"font-size:11pt\"><span style=\"unicode-bidi:embed\"><span style=\"line-height:115%\"><span style=\"font-family:Calibri,sans-serif\"><b>Help and support</b></span></span></span></span></p>\r\n\r\n<p style=\"text-align:justify; margin:0cm 0cm 10pt\"><span style=\"font-size:11pt\"><span style=\"unicode-bidi:embed\"><span style=\"line-height:115%\"><span style=\"font-family:Calibri,sans-serif\">There&rsquo;s even more to our promise to you: if you do everything required but you do not progress as expected, we will give you the additional lessons, help and support you need at no extra cost, to maximise your progress.*</span></span></span></span></p>\r\n\r\n<p style=\"text-align:justify; margin:0cm 0cm 10pt\"><span style=\"font-size:11pt\"><span style=\"unicode-bidi:embed\"><span style=\"line-height:115%\"><span style=\"font-family:Calibri,sans-serif\"><b>We promise you</b></span></span></span></span></p>\r\n\r\n<p style=\"text-align:justify; margin:0cm 0cm 10pt\"><span style=\"font-size:11pt\"><span style=\"unicode-bidi:embed\"><span style=\"line-height:115%\"><span style=\"font-family:Calibri,sans-serif\">A friendly learning environment.<br />\r\nA high standard of teaching and student welfare.<br />\r\nAppropriate facilities for language learning.<br />\r\nPractical ideas and guidance for personal study outside lesson times.<br />\r\nA varied social programme to complement your learning.<br />\r\nA quick response to any questions or problems.</span></span></span></span></p>\r\n\r\n<p style=\"text-align:justify; margin:0cm 0cm 10pt\">&nbsp;</p>\r\n\r\n<p style=\"text-align:justify; margin:0cm 0cm 10pt\"><span style=\"font-size:11pt\"><span style=\"unicode-bidi:embed\"><span style=\"line-height:115%\"><span style=\"font-family:Calibri,sans-serif\"><b>*Students who do not progress and wish to receive the Oxford Promise of extra lessons and support must contact their Director of Studies at least one week prior to departure. Other terms and conditions apply. Speak with your Oxford contact for more details.</b></span></span></span></span></p>', 'image' => 'uploads/image/image_1563639092.jpg', 'banner' => '/uploads/photos/shares/5d3ecfd112641.jpg', 'url' => null, 'tags' => 'gaza,oxford,ielts,english,score', 'status' => '1', 'age' => null, 'level' => null, 'weeks' => null, 'hours' => null, 'mock' => null, 'duration' => null, 'class_size' => null, 'fees' => null, 'price' => null, 'start' => null, 'days' => null, 'time' => null, 'created_at' => '2017-08-15 15:45:27', 'updated_at' => '2019-07-29 21:52:19', 'deleted_at' => null, ],
            ['id' => '3', 'title' => 'Oxford Family', 'slug' => 'family', 'details' => '<p class=\"rtin-content\"><strong>Tmply dummy text of the printing and typesetting industry. Lorem Ipsum has been theindustry&rsquo;s standard.</strong></p>\r\n\r\n<p>Smply dummy text of the printing and typesetting industry. Lorem Ipsum has been the industry&rsquo;s standard dummy text ever since the 1500s, when an unknown printer took a galley of type and scrambled it to make a type specimen book.Smply dummy text of the printing and typesetting industry. Lorem Ipsum has been the industry&rsquo;s when an unknown printerit to make a type specimen book.</p>', 'image' => 'image_1563348770.jpg', 'banner' => '/uploads/photos/shares/5d3ed325e2957.jpg', 'url' => null, 'tags' => 'oxford,gaza,english,test,centre,ielts,toefl,score', 'status' => '1', 'age' => null, 'level' => null, 'weeks' => null, 'hours' => null, 'mock' => null, 'duration' => null, 'class_size' => null, 'fees' => null, 'price' => null, 'start' => null, 'days' => null, 'time' => null, 'created_at' => '2017-08-15 15:45:27', 'updated_at' => '2019-07-29 22:06:25', 'deleted_at' => null, ],
            ['id' => '4', 'title' => 'Our Teaching Methods', 'slug' => 'methods', 'details' => '<p style=\"margin-bottom:9.6pt; text-align:left; margin:0cm 0cm 10pt\"><span style=\"font-size:11pt\"><span style=\"line-height:normal\"><span style=\"unicode-bidi:embed\"><span style=\"font-family:Calibri,sans-serif\"><span style=\"font-size:12.0pt\"><span style=\"font-family:&quot;Arial&quot;,&quot;sans-serif&quot;\"><span style=\"color:#333333\">From the first day you will be encouraged to use English in the classroom to communicate with the teacher and other students. The more you speak, the easier it becomes to learn the language. Our aim is to teach you in the most effective way possible, and in a fun and enjoyable environment.</span></span></span></span></span></span></span></p>\r\n\r\n<p style=\"margin-bottom:18.75pt; text-align:left; margin:0cm 0cm 10pt\"><span style=\"font-size:11pt\"><span style=\"line-height:normal\"><span style=\"unicode-bidi:embed\"><span style=\"font-family:Calibri,sans-serif\"><span style=\"font-size:12.0pt\"><span style=\"font-family:&quot;Arial&quot;,&quot;sans-serif&quot;\"><span style=\"color:#333333\">We believe that language learning is most successful when:</span></span></span></span></span></span></span></p>\r\n\r\n<ul>\r\n	<li style=\"margin-top:0cm; margin-right:7.5pt; margin-bottom:3.6pt; text-align:left; margin:0cm 0cm 10pt\"><span style=\"font-size:11pt\"><span style=\"line-height:normal\"><span style=\"tab-stops:list 36.0pt\"><span style=\"unicode-bidi:embed\"><span style=\"font-family:Calibri,sans-serif\"><span style=\"font-size:12.0pt\"><span style=\"font-family:&quot;Arial&quot;,&quot;sans-serif&quot;\"><span style=\"color:#333333\">it takes place in a stress-free environment</span></span></span></span></span></span></span></span></li>\r\n	<li style=\"margin-top:0cm; margin-right:7.5pt; margin-bottom:3.6pt; text-align:left; margin:0cm 0cm 10pt\"><span style=\"font-size:11pt\"><span style=\"line-height:normal\"><span style=\"tab-stops:list 36.0pt\"><span style=\"unicode-bidi:embed\"><span style=\"font-family:Calibri,sans-serif\"><span style=\"font-size:12.0pt\"><span style=\"font-family:&quot;Arial&quot;,&quot;sans-serif&quot;\"><span style=\"color:#333333\">students actively participate in lessons and are challenged and stimulated</span></span></span></span></span></span></span></span></li>\r\n	<li style=\"margin-top:0cm; margin-right:7.5pt; margin-bottom:3.6pt; text-align:left; margin:0cm 0cm 10pt\"><span style=\"font-size:11pt\"><span style=\"line-height:normal\"><span style=\"tab-stops:list 36.0pt\"><span style=\"unicode-bidi:embed\"><span style=\"font-family:Calibri,sans-serif\"><span style=\"font-size:12.0pt\"><span style=\"font-family:&quot;Arial&quot;,&quot;sans-serif&quot;\"><span style=\"color:#333333\">a variety of media and other activities are used to cater for all learning styles</span></span></span></span></span></span></span></span></li>\r\n	<li style=\"margin-top:0cm; margin-right:7.5pt; margin-bottom:3.6pt; text-align:left; margin:0cm 0cm 10pt\"><span style=\"font-size:11pt\"><span style=\"line-height:normal\"><span style=\"tab-stops:list 36.0pt\"><span style=\"unicode-bidi:embed\"><span style=\"font-family:Calibri,sans-serif\"><span style=\"font-size:12.0pt\"><span style=\"font-family:&quot;Arial&quot;,&quot;sans-serif&quot;\"><span style=\"color:#333333\">teachers are positive and supportive and have access to a wide range of teaching aids</span></span></span></span></span></span></span></span></li>\r\n	<li style=\"margin-top:0cm; margin-right:7.5pt; margin-bottom:3.6pt; text-align:left; margin:0cm 0cm 10pt\"><span style=\"font-size:11pt\"><span style=\"line-height:normal\"><span style=\"tab-stops:list 36.0pt\"><span style=\"unicode-bidi:embed\"><span style=\"font-family:Calibri,sans-serif\"><span style=\"font-size:12.0pt\"><span style=\"font-family:&quot;Arial&quot;,&quot;sans-serif&quot;\"><span style=\"color:#333333\">students&#39; progress is continually assessed in all areas of spoken and written English, based on work done in the classroom and at home.</span></span></span></span></span></span></span></span></li>\r\n</ul>\r\n\r\n<p style=\"margin-bottom:.0001pt; text-align:justify; margin:0cm 0cm 10pt\">&nbsp;</p>\r\n\r\n<p style=\"margin-bottom:.0001pt; text-align:left; margin:0cm 0cm 10pt\"><span style=\"font-size:11pt\"><span style=\"background:white\"><span style=\"line-height:normal\"><span style=\"vertical-align:baseline\"><span style=\"unicode-bidi:embed\"><span style=\"font-family:Calibri,sans-serif\"><span style=\"font-size:12.0pt\"><span style=\"font-family:&quot;Arial&quot;,&quot;sans-serif&quot;\"><span style=\"color:#646a6a\"><img alt=\"We love what we do\" src=\"data:image/png;base64,\" style=\"width:95px; height:93px\" /></span></span></span></span></span></span></span></span></span></p>\r\n\r\n<p style=\"margin-bottom:15.0pt; text-align:left; margin:0cm 0cm 10pt\"><span style=\"font-size:11pt\"><span style=\"line-height:normal\"><span style=\"vertical-align:baseline\"><span style=\"unicode-bidi:embed\"><span style=\"font-family:Calibri,sans-serif\"><b><span style=\"font-size:13.5pt\"><span style=\"font-family:&quot;Arial&quot;,&quot;sans-serif&quot;\"><span style=\"color:#10151a\">We love what we do</span></span></span></b></span></span></span></span></span></p>\r\n\r\n<p style=\"margin-bottom:15.0pt; text-align:left; margin:0cm 0cm 10pt\"><span style=\"font-size:11pt\"><span style=\"line-height:normal\"><span style=\"vertical-align:baseline\"><span style=\"unicode-bidi:embed\"><span style=\"font-family:Calibri,sans-serif\"><span style=\"font-size:12.0pt\"><span style=\"font-family:&quot;Arial&quot;,&quot;sans-serif&quot;\"><span style=\"color:#646a6a\">Teaching English isn&rsquo;t just a job for us, it&rsquo;s a passion. We take pride in our students&#39; achievements.</span></span></span></span></span></span></span></span></p>\r\n\r\n<p style=\"margin-bottom:.0001pt; text-align:left; margin:0cm 0cm 10pt\"><span style=\"font-size:11pt\"><span style=\"background:white\"><span style=\"line-height:normal\"><span style=\"vertical-align:baseline\"><span style=\"unicode-bidi:embed\"><span style=\"font-family:Calibri,sans-serif\"><span style=\"font-size:12.0pt\"><span style=\"font-family:&quot;Arial&quot;,&quot;sans-serif&quot;\"><span style=\"color:#646a6a\"><img alt=\"We go the extra mile\" src=\"data:image/png;base64,\" style=\"width:95px; height:93px\" /></span></span></span></span></span></span></span></span></span></p>\r\n\r\n<p style=\"margin-bottom:15.0pt; text-align:left; margin:0cm 0cm 10pt\"><span style=\"font-size:11pt\"><span style=\"line-height:normal\"><span style=\"vertical-align:baseline\"><span style=\"unicode-bidi:embed\"><span style=\"font-family:Calibri,sans-serif\"><b><span style=\"font-size:13.5pt\"><span style=\"font-family:&quot;Arial&quot;,&quot;sans-serif&quot;\"><span style=\"color:#10151a\">We go the extra mile</span></span></span></b></span></span></span></span></span></p>\r\n\r\n<p style=\"margin-bottom:15.0pt; text-align:left; margin:0cm 0cm 10pt\"><span style=\"font-size:11pt\"><span style=\"line-height:normal\"><span style=\"vertical-align:baseline\"><span style=\"unicode-bidi:embed\"><span style=\"font-family:Calibri,sans-serif\"><span style=\"font-size:12.0pt\"><span style=\"font-family:&quot;Arial&quot;,&quot;sans-serif&quot;\"><span style=\"color:#646a6a\">As far as we&rsquo;re concerned there&rsquo;s no such thing as &lsquo;good enough&rsquo;. We do a great job and then go further, doing whatever it takes to achieve success on your behalf.</span></span></span></span></span></span></span></span></p>\r\n\r\n<p style=\"margin-bottom:.0001pt; text-align:left; margin:0cm 0cm 10pt\"><span style=\"font-size:11pt\"><span style=\"background:white\"><span style=\"line-height:normal\"><span style=\"vertical-align:baseline\"><span style=\"unicode-bidi:embed\"><span style=\"font-family:Calibri,sans-serif\"><span style=\"font-size:12.0pt\"><span style=\"font-family:&quot;Arial&quot;,&quot;sans-serif&quot;\"><span style=\"color:#646a6a\"><img alt=\"We deliver what we promise\" src=\"data:image/png;base64,\" style=\"width:95px; height:93px\" /></span></span></span></span></span></span></span></span></span></p>\r\n\r\n<p style=\"margin-bottom:15.0pt; text-align:left; margin:0cm 0cm 10pt\"><span style=\"font-size:11pt\"><span style=\"line-height:normal\"><span style=\"vertical-align:baseline\"><span style=\"unicode-bidi:embed\"><span style=\"font-family:Calibri,sans-serif\"><b><span style=\"font-size:13.5pt\"><span style=\"font-family:&quot;Arial&quot;,&quot;sans-serif&quot;\"><span style=\"color:#10151a\">We deliver what we promise</span></span></span></b></span></span></span></span></span></p>\r\n\r\n<p style=\"margin-bottom:15.0pt; text-align:left; margin:0cm 0cm 10pt\"><span style=\"font-size:11pt\"><span style=\"line-height:normal\"><span style=\"vertical-align:baseline\"><span style=\"unicode-bidi:embed\"><span style=\"font-family:Calibri,sans-serif\"><span style=\"font-size:12.0pt\"><span style=\"font-family:&quot;Arial&quot;,&quot;sans-serif&quot;\"><span style=\"color:#646a6a\">The results we offer aren&rsquo;t simply an aspiration or target, they&rsquo;re guaranteed. When you study with us you know that we&rsquo;ll make sure you meet your goals.</span></span></span></span></span></span></span></span></p>\r\n\r\n<p style=\"margin-bottom:.0001pt; text-align:left; margin:0cm 0cm 10pt\"><span style=\"font-size:11pt\"><span style=\"background:white\"><span style=\"line-height:normal\"><span style=\"vertical-align:baseline\"><span style=\"unicode-bidi:embed\"><span style=\"font-family:Calibri,sans-serif\"><span style=\"font-size:12.0pt\"><span style=\"font-family:&quot;Arial&quot;,&quot;sans-serif&quot;\"><span style=\"color:#646a6a\"><img alt=\"We have a can-do mindset\" src=\"data:image/png;base64,\" style=\"width:95px; height:93px\" /></span></span></span></span></span></span></span></span></span></p>\r\n\r\n<p style=\"margin-bottom:15.0pt; text-align:left; margin:0cm 0cm 10pt\"><span style=\"font-size:11pt\"><span style=\"line-height:normal\"><span style=\"vertical-align:baseline\"><span style=\"unicode-bidi:embed\"><span style=\"font-family:Calibri,sans-serif\"><b><span style=\"font-size:13.5pt\"><span style=\"font-family:&quot;Arial&quot;,&quot;sans-serif&quot;\"><span style=\"color:#10151a\">We have a can-do mindset</span></span></span></b></span></span></span></span></span></p>\r\n\r\n<p style=\"margin-bottom:15.0pt; text-align:left; margin:0cm 0cm 10pt\"><span style=\"font-size:11pt\"><span style=\"line-height:normal\"><span style=\"vertical-align:baseline\"><span style=\"unicode-bidi:embed\"><span style=\"font-family:Calibri,sans-serif\"><span style=\"font-size:12.0pt\"><span style=\"font-family:&quot;Arial&quot;,&quot;sans-serif&quot;\"><span style=\"color:#646a6a\">We see opportunities, not problems. We concentrate on how much you can achieve, instead of the things you can&#39;t do.</span></span></span></span></span></span></span></span></p>', 'image' => 'uploads/image/image_1563638626.jpg', 'banner' => '/uploads/photos/shares/5d3ed6d6eaaa7.jpg', 'url' => null, 'tags' => 'oxford,gaza,ielts,english,score,toefl,centre', 'status' => '1', 'age' => null, 'level' => null, 'weeks' => null, 'hours' => null, 'mock' => null, 'duration' => null, 'class_size' => null, 'fees' => null, 'price' => null, 'start' => null, 'days' => null, 'time' => null, 'created_at' => '2017-08-15 15:45:27', 'updated_at' => '2019-07-29 22:23:56', 'deleted_at' => null, ],
            ['id' => '5', 'title' => 'Partners', 'slug' => 'partners', 'details' => '<p class=\"rtin-content\"><strong>Tmply dummy text of the printing and typesetting industry. Lorem Ipsum has been theindustry&rsquo;s standard.</strong></p>\r\n\r\n<p>Smply dummy text of the printing and typesetting industry. Lorem Ipsum has been the industry&rsquo;s standard dummy text ever since the 1500s, when an unknown printer took a galley of type and scrambled it to make a type specimen book.Smply dummy text of the printing and typesetting industry. Lorem Ipsum has been the industry&rsquo;s when an unknown printerit to make a type specimen book.</p>', 'image' => 'image_1563348770.jpg', 'banner' => '/uploads/photos/shares/5d3ed84e7b9cd.jpg', 'url' => null, 'tags' => 'oxford ,english,ielts,toefl,test,level,score', 'status' => '1', 'age' => null, 'level' => null, 'weeks' => null, 'hours' => null, 'mock' => null, 'duration' => null, 'class_size' => null, 'fees' => null, 'price' => null, 'start' => null, 'days' => null, 'time' => null, 'created_at' => '2017-08-15 15:45:27', 'updated_at' => '2019-07-29 22:28:24', 'deleted_at' => null, ],
            ['id' => '6', 'title' => 'IELTS Preparation Course', 'slug' => 'ielts', 'details' => '<table class=\"Table\" style=\"width:100.0%; border-collapse:collapse; border:undefined\" width=\"100%\">\r\n	<tbody>\r\n		<tr>\r\n			<td style=\"padding:7.5pt 7.5pt 7.5pt 15.0pt\" valign=\"top\">\r\n			<p style=\"text-align: justify; margin: 0cm 0cm 10pt;\"><strong>Improve Your Academic and Professional Life and Start with IELTS for a Better Future</strong></p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td style=\"padding:7.5pt 7.5pt 7.5pt 15.0pt\" valign=\"top\">\r\n			<p style=\"text-align: justify; margin: 0cm 0cm 10pt;\"><span style=\"font-size:11pt\"><span style=\"unicode-bidi:embed\"><span style=\"line-height:115%\"><span style=\"font-family:Calibri,sans-serif\"><b>IELTS</b> &ndash; the International English Language Testing System &ndash; is the world&rsquo;s most popular English language test. It is developed by some of the world&rsquo;s leading experts in language assessment and evaluates all of your English skills reading, writing, listening and speaking. The test reflects how you&rsquo;ll use English to study, work and live in an English speaking environment.</span></span></span></span></p>\r\n\r\n			<p style=\"text-align: justify; margin: 0cm 0cm 10pt;\"><span style=\"font-size:11pt\"><span style=\"unicode-bidi:embed\"><span style=\"line-height:115%\"><span style=\"font-family:Calibri,sans-serif\">We believe that just doing practice IELTS exams and exercises is not the best way to raise your IELTS level. To be successful in this exam you need a wide range of vocabulary and syntax. Our course is designed to build these areas using engaging, authentic situations while providing plenty of exam skills and practice. Through weekly reviews and coaching,</span></span></span></span></p>\r\n\r\n			<p style=\"text-align: justify; margin: 0cm 0cm 10pt;\"><span style=\"font-size:11pt\"><span style=\"unicode-bidi:embed\"><span style=\"line-height:115%\"><span style=\"font-family:Calibri,sans-serif\">monthly tests, regular filming and mock IELTS tests we measure your progress clearly and visibly to highlight strengths, needs and objectives.</span></span></span></span></p>\r\n\r\n			<p style=\"text-align: justify; margin: 0cm 0cm 10pt;\"><span style=\"font-size:11pt\"><span style=\"unicode-bidi:embed\"><span style=\"line-height:115%\"><span style=\"font-family:Calibri,sans-serif\"><b>Our course helps you to:</b></span></span></span></span></p>\r\n\r\n			<p style=\"text-align: justify; margin: 0cm 0cm 10pt;\"><span style=\"font-size:11pt\"><span style=\"unicode-bidi:embed\"><span style=\"line-height:115%\"><span style=\"font-family:Calibri,sans-serif\">&bull; be confident in handling all aspects of the exam</span></span></span></span></p>\r\n\r\n			<p style=\"text-align: justify; margin: 0cm 0cm 10pt;\"><span style=\"font-size:11pt\"><span style=\"unicode-bidi:embed\"><span style=\"line-height:115%\"><span style=\"font-family:Calibri,sans-serif\">&bull; express your thoughts and opinions fluently</span></span></span></span></p>\r\n\r\n			<p style=\"text-align: justify; margin: 0cm 0cm 10pt;\"><span style=\"font-size:11pt\"><span style=\"unicode-bidi:embed\"><span style=\"line-height:115%\"><span style=\"font-family:Calibri,sans-serif\">&bull; use grammar and vocabulary effectively</span></span></span></span></p>\r\n\r\n			<p style=\"text-align: justify; margin: 0cm 0cm 10pt;\"><span style=\"font-size:11pt\"><span style=\"unicode-bidi:embed\"><span style=\"line-height:115%\"><span style=\"font-family:Calibri,sans-serif\">&bull; overcome anxiety with intensive exam practice</span></span></span></span></p>\r\n			</td>\r\n		</tr>\r\n	</tbody>\r\n</table>', 'image' => 'uploads/image/image_1566043474.jpg', 'banner' => '/uploads/photos/shares/5d3edadd4febf.jpg', 'url' => null, 'tags' => 'الرئيسية,صفحة,صفحة ثابتة,ثابتة', 'status' => '1', 'age' => '16 years old and older', 'level' => 'Intermediate and above', 'weeks' => '5 weeks', 'hours' => '30 hours', 'mock' => '3 (hours 10)', 'duration' => '15 sessions (2 hours each)', 'class_size' => 'Average 10, Maximum 15', 'fees' => '100Nis', 'price' => '100$', 'start' => 'Monthly', 'days' => 'Saturday-Monday-Wednesday / Sunday-Tuesday-Thursday', 'time' => '10-12 am / 2-4 pm / 4-6 pm', 'created_at' => '2017-08-15 15:45:27', 'updated_at' => '2019-08-19 02:21:13', 'deleted_at' => null, ],
            ['id' => '7', 'title' => 'General English Levels (CEFRL)', 'slug' => 'general', 'details' => '<p style=\"text-align:left; margin:0cm 0cm 10pt\"><span style=\"font-size:11pt\"><span style=\"unicode-bidi:embed\"><span style=\"line-height:115%\"><span style=\"font-family:Calibri,sans-serif\">Our General English courses It covers reading, writing, speaking, listening, grammar, vocabulary and critical thinking. In this class you&#39;ll improve your accuracy (how correct your English is) and fluency (how well you can communicate). Lessons have daily and weekly objectives so you know what you&rsquo;ll learn and how you&rsquo;ll learn it.&nbsp;Our teachers provide you with regular assessments that allow you to keep track of your progress.</span></span></span></span></p>\r\n\r\n<p style=\"text-align:left; margin:0cm 0cm 10pt\"><span style=\"font-size:11pt\"><span style=\"unicode-bidi:embed\"><span style=\"line-height:115%\"><span style=\"font-family:Calibri,sans-serif\">&nbsp;We use the Communicative Approach, so you&#39;ll learn English by using English not by listening to grammar lectures and doing worksheets. We feel strongly that this is the most effective method to acquire English that students can use in the real world.</span></span></span></span></p>\r\n\r\n<p class=\"rtin-content\"><span style=\"font-size:11.0pt\"><span style=\"line-height:115%\"><span style=\"font-family:&quot;Calibri&quot;,&quot;sans-serif&quot;\">The Syllabus for each level is mapped to the&nbsp;<a href=\"https://oxford.ps/oxford_description_of_levels_2019.pdf\" style=\"color:blue; text-decoration:underline\" target=\"_blank\">CEFR levels A1-C1</a>. The levels define what you can do and Oxford English Centre believes that language is for communication. Each of our Core Class Course Books is also mapped to the CEFR providing a consistent basis for developing your language skills.&nbsp;</span></span></span></p>', 'image' => 'uploads/image/image_1566043245.jpg', 'banner' => '/uploads/photos/shares/5d3edbdd4f0d0.jpg', 'url' => null, 'tags' => 'reading , writing, speaking, listening, grammar, vocabulary,english,course,ielts,test,score,toefl,oxford,gaza', 'status' => '1', 'age' => '16 Year old And Older', 'level' => 'A1 - C1', 'weeks' => '10 weeks', 'hours' => '60 hours', 'mock' => null, 'duration' => '30 sessions (2 hours each)', 'class_size' => 'Average 10, Maximum 15', 'fees' => '50Nis', 'price' => '200$', 'start' => 'Monthly', 'days' => 'Saturday-Monday-Wednesday / Sunday-Tuesday-Thursday', 'time' => '10-12 am / 2-4 pm / 4-6 pm', 'created_at' => '2017-08-15 15:45:27', 'updated_at' => '2019-08-20 21:13:45', 'deleted_at' => null, ],
            ['id' => '8', 'title' => 'Speaking Course', 'slug' => 'speaking', 'details' => '<p style=\"text-align:justify; margin:0cm 0cm 10pt\"><strong><span style=\"font-size:11pt\"><span style=\"unicode-bidi:embed\"><span style=\"line-height:115%\"><span style=\"font-family:Calibri,sans-serif\">Our Focus on Speaking course combines self-study vocabulary exercises and a focus on natural English pronunciation with intensive speaking practice.</span></span></span></span></strong></p>\r\n\r\n<p style=\"text-align:justify; margin:0cm 0cm 10pt\"><span style=\"font-size:11pt\"><span style=\"unicode-bidi:embed\"><span style=\"line-height:115%\"><span style=\"font-family:Calibri,sans-serif\">Using material from a specially designed workbook, you will do a variety of communicative tasks and your teacher will give you advice about how you can improve the fluency and accuracy of your spoken English.</span></span></span></span></p>\r\n\r\n<p style=\"text-align:justify; margin:0cm 0cm 10pt\">&nbsp;</p>\r\n\r\n<p style=\"text-align:justify; margin:0cm 0cm 10pt\"><strong><span style=\"font-size:11pt\"><span style=\"unicode-bidi:embed\"><span style=\"line-height:115%\"><span style=\"font-family:Calibri,sans-serif\">TAKE A FOCUS ON SPEAKING COURSE AND YOU WILL:</span></span></span></span></strong></p>\r\n\r\n<ul>\r\n	<li style=\"margin-right:0cm; text-align:justify; margin:0cm 0cm 10pt\"><span style=\"font-size:11pt\"><span style=\"tab-stops:list 36.0pt\"><span style=\"unicode-bidi:embed\"><span style=\"line-height:115%\"><span style=\"font-family:Calibri,sans-serif\">Get a qualified and experienced teacher</span></span></span></span></span></li>\r\n	<li style=\"margin-right:0cm; text-align:justify; margin:0cm 0cm 10pt\"><span style=\"font-size:11pt\"><span style=\"tab-stops:list 36.0pt\"><span style=\"unicode-bidi:embed\"><span style=\"line-height:115%\"><span style=\"font-family:Calibri,sans-serif\">Work in pairs and groups to discuss six different topics</span></span></span></span></span></li>\r\n	<li style=\"margin-right:0cm; text-align:justify; margin:0cm 0cm 10pt\"><span style=\"font-size:11pt\"><span style=\"tab-stops:list 36.0pt\"><span style=\"unicode-bidi:embed\"><span style=\"line-height:115%\"><span style=\"font-family:Calibri,sans-serif\">Improve your pronunciation</span></span></span></span></span></li>\r\n	<li style=\"margin-right:0cm; text-align:justify; margin:0cm 0cm 10pt\"><span style=\"font-size:11pt\"><span style=\"tab-stops:list 36.0pt\"><span style=\"unicode-bidi:embed\"><span style=\"line-height:115%\"><span style=\"font-family:Calibri,sans-serif\">Enjoy speaking English.</span></span></span></span></span></li>\r\n</ul>\r\n\r\n<p style=\"text-align:justify; margin:0cm 0cm 10pt\">&nbsp;</p>\r\n\r\n<p class=\"rtin-content\"><strong><span style=\"font-size:11.0pt\"><span style=\"line-height:115%\"><span style=\"font-family:&quot;Calibri&quot;,&quot;sans-serif&quot;\">The course is designed to increase your active vocabulary and give you more confidence and control when speaking in English. Many students will take a General English&nbsp;and&nbsp;a Focus on Speaking course</span></span></span></strong></p>', 'image' => 'uploads/image/image_1566044079.jpg', 'banner' => '/uploads/photos/shares/5d3edc974b6fb.jpg', 'url' => null, 'tags' => 'Speaking Course,vocabulary ,english,ielts,score,gaza,toefl,test', 'status' => '1', 'age' => '16 years old and older', 'level' => 'Intermediate and above', 'weeks' => '5 weeks', 'hours' => '30 hours', 'mock' => null, 'duration' => '15 sessions (2 hours each)', 'class_size' => 'Average 8, Maximum 12', 'fees' => null, 'price' => '100$', 'start' => 'Monthly', 'days' => 'Saturday-Monday-Wednesday / Sunday-Tuesday-Thursday', 'time' => '10-12 am / 2-4 pm / 4-6 pm', 'created_at' => '2017-08-15 15:45:27', 'updated_at' => '2019-08-20 21:14:23', 'deleted_at' => null, ],
            ['id' => '9', 'title' => 'Academic WritIng Course', 'slug' => 'writing', 'details' => '<p><strong>Improve your written English abilities for work, study and life</strong></p>\r\n\r\n<p>This is the ideal course if you need to improve your writing skills to achieve success at university either at under-graduate or post-graduate level. This course will help you develop your planning, drafting and editing skills which are essential when writing a dissertation or thesis. You will also practise techniques and language to give your written style a more formal and academic tone.</p>\r\n\r\n<p>You will complete five writing tasks and receive personalised feedback and counselling from your teacher.</p>\r\n\r\n<p>&nbsp;<strong>ON THIS COURSE YOU WILL:</strong></p>\r\n\r\n<ul>\r\n	<li>&nbsp;Learn to structure and organise a range of written texts</li>\r\n	<li>&nbsp;Practice planning and editing your own writing</li>\r\n	<li>&nbsp;Learn phrases and vocabulary typical in academic writing</li>\r\n	<li>&nbsp;Create a portfolio to showcase your written work</li>\r\n</ul>\r\n\r\n<p><strong>WHY SHOULD YOU CHOOSE THIS COURSE FROM THE OXFORD ENGLISH CENTRE?</strong></p>\r\n\r\n<p>Be taught by highly qualified teacher</p>\r\n\r\n<ul>\r\n	<li>Enjoy lessons that use modern teaching methods and materials.</li>\r\n	<li>Gain access to the LearnEnglish website featuring thousands of hints, tips, games and downloads</li>\r\n	<li>See your ability to plan and write a range of academic texts improve</li>\r\n</ul>\r\n\r\n<p><strong>HOW IS THIS COURSE STRUCTURED?</strong></p>\r\n\r\n<p>This course is for students placed at intermediate and above. Your teacher will introduce different types of written texts typically needed at university or in higher education. You will write a number of essays and analyse typical features in other genres such as personal statements and reports.</p>\r\n\r\n<p>You will need to take a placement test to determine that your writing skills are at the appropriate level.</p>', 'image' => 'uploads/image/image_1565256153.jpg', 'banner' => '/uploads/photos/shares/5d3ede225bf0d.jpg', 'url' => null, 'tags' => 'Academic  WritIng  Course,english,score,ielts,gaza,toefl,test,study ,university', 'status' => '1', 'age' => '16 years old and older', 'level' => 'Intermediate and above', 'weeks' => '5 weeks', 'hours' => '30 hours', 'mock' => null, 'duration' => '15 sessions (2 hours each)', 'class_size' => 'Average 10, Maximum 15', 'fees' => null, 'price' => '150 $', 'start' => 'Monthly', 'days' => 'Saturday-Monday-Wednesday / Sunday-Tuesday-Thursday', 'time' => '10-12 am / 2-4 pm / 4-6 pm', 'created_at' => '2017-08-15 15:45:27', 'updated_at' => '2019-08-20 21:11:32', 'deleted_at' => null, ],
            ['id' => '10', 'title' => 'Business English Course', 'slug' => 'business', 'details' => '<h3><strong>Improve your confidence and impact in today&rsquo;s global business world</strong></h3>\r\n\r\n<p><strong>Our business English courses focus on the situations that are most relevant to</strong>&nbsp;<strong>your employees&#39; everyday working lives.</strong></p>\r\n\r\n<p>The teacher will select materials to help with the specific areas&nbsp;they need to&nbsp;improve. These include negotiating skills, emailing, giving presentations, managing meetings and more.</p>\r\n\r\n<p><strong>Learn the world&rsquo;s business language with Oxford your employees&nbsp;will:</strong></p>\r\n\r\n<ol>\r\n	<li>improve every aspect of their English to communicate better in the workplace&nbsp;</li>\r\n	<li>use targeted, up-to-date business materials that help with the specific areas&nbsp;they need&nbsp;to improve</li>\r\n	<li>meet other professionals, share business ideas and solutions and build&nbsp;their professional network</li>\r\n	<li>experience business focused lessons, allowing them to practice English through role-plays, presentations and written tasks</li>\r\n	<li>learn in a professional, business-like environment with all the latest technology</li>\r\n</ol>\r\n\r\n<p><strong>FAQs</strong></p>\r\n\r\n<p><strong>Do I need to take an entry test before I book?</strong></p>\r\n\r\n<p>No, you&rsquo;ll be tested on arrival to make sure you&rsquo;re in a class that&rsquo;s just right for your level.</p>\r\n\r\n<p>&nbsp;</p>', 'image' => 'uploads/image/image_1566045041.jpg', 'banner' => '/uploads/photos/shares/5d3edfb8a0000.jpg', 'url' => null, 'tags' => 'Business English Course,ielts,gaza,oxford,toefl,test,business ,level', 'status' => '1', 'age' => '16 years old and older', 'level' => 'Intermediate and above', 'weeks' => '5 weeks', 'hours' => '30 hours', 'mock' => null, 'duration' => '15 sessions (2 hours each)', 'class_size' => 'Average 10, Maximum 15', 'fees' => null, 'price' => '150 $', 'start' => 'Monthly', 'days' => 'Saturday-Monday-Wednesday / Sunday-Tuesday-Thursday', 'time' => '10-12 am / 2-4 pm / 4-6 pm', 'created_at' => '2017-08-15 15:45:27', 'updated_at' => '2019-08-20 21:12:05', 'deleted_at' => null, ],
            ['id' => '11', 'title' => 'English for Specific Purposes - ESP', 'slug' => 'esp', 'details' => '<p style=\"text-align:left; margin:0cm 0cm 10pt\"><span style=\"font-size:11pt\"><span style=\"unicode-bidi:embed\"><span style=\"line-height:115%\"><span style=\"font-family:Calibri,sans-serif\"><b>English for Specific Purposes, or ESP, refers to learning English because you have a specific need. It can include the area of EPP, English for Professional Purposes.</b></span></span></span></span></p>\r\n\r\n<p style=\"text-align:left; margin:0cm 0cm 10pt\"><span style=\"font-size:11pt\"><span style=\"unicode-bidi:embed\"><span style=\"line-height:115%\"><span style=\"font-family:Calibri,sans-serif\">Our ESP courses are designed to help you improve your English in a specific professional context. Where a business English programme tends to provide a general approach to formal English, ESP courses are workplace-specific and focus on how English is used in fields such as IT, medicine and finance . </span></span></span></span></p>\r\n\r\n<p style=\"text-align:left; margin:0cm 0cm 10pt\"><span style=\"font-size:11pt\"><span style=\"unicode-bidi:embed\"><span style=\"line-height:115%\"><span style=\"font-family:Calibri,sans-serif\"><b>Example</b></span></span></span></span></p>\r\n\r\n<p style=\"text-align:left; margin:0cm 0cm 10pt\"><span style=\"font-size:11pt\"><span style=\"unicode-bidi:embed\"><span style=\"line-height:115%\"><span style=\"font-family:Calibri,sans-serif\">Survival English for immigrants, English for Hotel Management, and English for Air Traffic Controllers are all ESP<span dir=\"RTL\" lang=\"AR-SA\" style=\"font-family:&quot;Arial&quot;,&quot;sans-serif&quot;\">.</span></span></span></span></span></p>\r\n\r\n<p style=\"text-align:left; margin:0cm 0cm 10pt\"><span style=\"font-size:11pt\"><span style=\"unicode-bidi:embed\"><span style=\"line-height:115%\"><span style=\"font-family:Calibri,sans-serif\"><b>In the classroom</b></span></span></span></span></p>\r\n\r\n<p style=\"text-align:left; margin:0cm 0cm 10pt\"><span style=\"font-size:11pt\"><span style=\"unicode-bidi:embed\"><span style=\"line-height:115%\"><span style=\"font-family:Calibri,sans-serif\">Asking learners what they need to learn is an important element of ESP classes, as often their language needs and aims are very specific. This data can then be combined with the teacher&#39;s analysis of core language and learning needs in order to prepare a syllabus.</span></span></span></span></p>', 'image' => 'uploads/image/image_1566044323.jpg', 'banner' => '/uploads/photos/shares/5d3ee0ee9585f.jpg', 'url' => null, 'tags' => 'English for Specific Purposes - ESP,esp,oxford,english,centre,ielts,toefl,levels,score', 'status' => '1', 'age' => '16 years old and older', 'level' => 'A1 - C1', 'weeks' => '5 weeks', 'hours' => '30 hours', 'mock' => null, 'duration' => '15 sessions (2 hours each)', 'class_size' => 'Average 10, Maximum 15', 'fees' => null, 'price' => '150 $', 'start' => 'Monthly', 'days' => 'Saturday-Monday-Wednesday / Sunday-Tuesday-Thursday', 'time' => '10-12 am / 2-4 pm / 4-6 pm', 'created_at' => '2017-08-15 15:45:27', 'updated_at' => '2019-08-20 21:12:59', 'deleted_at' => null, ],
            ['id' => '12', 'title' => 'Oxford IELTS Prize', 'slug' => 'prize', 'details' => '<p align=\"center\" dir=\"RTL\" style=\"margin-top:0cm; margin-right:-9.95pt; margin-bottom:.0001pt; margin-left:0cm; text-align:center; margin:0cm 0cm 10pt\"><span style=\"font-size:11pt\"><span style=\"line-height:normal\"><span style=\"vertical-align:baseline\"><span style=\"unicode-bidi:embed\"><span style=\"font-family:Calibri,sans-serif\"><strong><span style=\"border:none windowtext 1.0pt; background:white; padding:0cm\"><span style=\"font-family:&quot;Verdana&quot;,&quot;sans-serif&quot;\"><span style=\"color:#3e493e\">Oxford English Centre is offering 5 IELTS fee Prize every year to students of Oxford who <u>score 8.0 and above in their IELTS test.</u></span></span></span></strong></span></span></span></span></span></p>\r\n\r\n<p align=\"center\" dir=\"RTL\" style=\"margin-top:0cm; margin-right:-9.95pt; margin-bottom:.0001pt; margin-left:0cm; text-align:center; margin:0cm 0cm 10pt\">&nbsp;</p>\r\n\r\n<p dir=\"LTR\" style=\"margin-bottom:.0001pt; text-align:left; margin:0cm 0cm 10pt; margin-right:0cm; margin-left:0cm\"><span style=\"font-size:11pt\"><span style=\"line-height:normal\"><span style=\"vertical-align:baseline\"><span style=\"unicode-bidi:embed\"><span style=\"font-family:Calibri,sans-serif\"><b><span style=\"border:none windowtext 1.0pt; font-family:&quot;Verdana&quot;,&quot;sans-serif&quot;; padding:0cm\"><span style=\"color:#3e493e\">Why we are offering Oxford IELTS Prize </span></span></b></span></span></span></span></span></p>\r\n\r\n<p dir=\"LTR\" style=\"margin-bottom:.0001pt; text-align:left; margin:0cm 0cm 10pt; margin-right:0cm; margin-left:0cm\"><span style=\"font-size:11pt\"><span style=\"line-height:normal\"><span style=\"vertical-align:baseline\"><span style=\"unicode-bidi:embed\"><span style=\"font-family:Calibri,sans-serif\"><span style=\"font-family:&quot;Verdana&quot;,&quot;sans-serif&quot;\"><span style=\"color:#3e493e\">We offer Oxford Prize as a humble contribution to the local community and as a gesture of encouragement to our students.</span></span></span></span></span></span></span></p>\r\n\r\n<p dir=\"LTR\" style=\"margin-bottom:.0001pt; text-align:left; margin:0cm 0cm 10pt; margin-right:0cm; margin-left:0cm\"><span style=\"font-size:11pt\"><span style=\"line-height:normal\"><span style=\"vertical-align:baseline\"><span style=\"unicode-bidi:embed\"><span style=\"font-family:Calibri,sans-serif\"><b><span style=\"border:none windowtext 1.0pt; font-family:&quot;Verdana&quot;,&quot;sans-serif&quot;; padding:0cm\"><span style=\"color:#3e493e\">What is an OXFORD IELTS Prize?</span></span></b></span></span></span></span></span><br />\r\n<span style=\"font-size:11pt\"><span style=\"line-height:normal\"><span style=\"vertical-align:baseline\"><span style=\"unicode-bidi:embed\"><span style=\"font-family:Calibri,sans-serif\"><span style=\"font-family:&quot;Verdana&quot;,&quot;sans-serif&quot;\"><span style=\"color:#3e493e\">It will cover the cost (currently 1000 NIS) of registering to take an IELTS test for 5 candidates every year. If you get a score of 8.0 or above in the test.</span></span></span></span></span></span></span></p>\r\n\r\n<p dir=\"LTR\" style=\"margin-bottom:.0001pt; text-align:left; margin:0cm 0cm 10pt; margin-right:0cm; margin-left:0cm\"><span style=\"font-size:11pt\"><span style=\"line-height:normal\"><span style=\"vertical-align:baseline\"><span style=\"unicode-bidi:embed\"><span style=\"font-family:Calibri,sans-serif\"><b><span style=\"border:none windowtext 1.0pt; font-family:&quot;Verdana&quot;,&quot;sans-serif&quot;; padding:0cm\"><span style=\"color:#3e493e\">How to apply</span></span></b><br />\r\n<span style=\"font-family:&quot;Verdana&quot;,&quot;sans-serif&quot;\"><span style=\"color:#3e493e\">If you wish to apply for Oxford Prize, you should complete the application form and send us a copy of your IELTS certificate at: </span></span><a href=\"mailto:info@oxford.ps\" style=\"color:blue; text-decoration:underline\"><span style=\"font-family:&quot;Verdana&quot;,&quot;sans-serif&quot;\">info@oxford.ps</span></a><span style=\"font-family:&quot;Verdana&quot;,&quot;sans-serif&quot;\"><span style=\"color:#3e493e\">. </span></span></span></span></span></span></span></p>\r\n\r\n<p dir=\"LTR\" style=\"margin-bottom:.0001pt; text-align:left; margin:0cm 0cm 10pt; margin-right:0cm; margin-left:0cm\">&nbsp;</p>\r\n\r\n<p dir=\"LTR\" style=\"margin:0cm; margin-bottom:.0001pt; margin-right:0cm; margin-left:0cm\"><span style=\"font-size:12pt\"><span style=\"vertical-align:baseline\"><span style=\"font-family:&quot;Times New Roman&quot;,serif\"><strong><span style=\"border:none windowtext 1.0pt; font-size:11.0pt; padding:0cm\"><span style=\"font-family:&quot;Verdana&quot;,&quot;sans-serif&quot;\"><span style=\"color:#3e493e\">To get the Oxford IELTS Prize application form please contact </span></span></span></strong></span></span></span></p>\r\n\r\n<p dir=\"LTR\" style=\"margin:0cm; margin-bottom:.0001pt; margin-right:0cm; margin-left:0cm\"><span style=\"font-size:12pt\"><span style=\"vertical-align:baseline\"><span style=\"font-family:&quot;Times New Roman&quot;,serif\"><strong><span style=\"border:none windowtext 1.0pt; font-size:11.0pt; padding:0cm\"><span style=\"font-family:&quot;Verdana&quot;,&quot;sans-serif&quot;\"><span style=\"color:#3e493e\">Mr. IBRAHIM ALMASRI&nbsp;+970592872188&nbsp;</span></span></span></strong></span></span></span></p>', 'image' => 'uploads/image/image_1566045713.jpg', 'banner' => '/uploads/photos/shares/5d3ee1c81b087.jpg', 'url' => null, 'tags' => 'Oxford IELTS Prize,oxford,ielts,prize,toefl,gaza,level,english,test', 'status' => '1', 'age' => null, 'level' => null, 'weeks' => null, 'hours' => null, 'mock' => null, 'duration' => null, 'class_size' => null, 'fees' => null, 'price' => null, 'start' => null, 'days' => null, 'time' => null, 'created_at' => '2017-08-15 15:45:27', 'updated_at' => '2023-09-17 14:19:47', 'deleted_at' => null, ],
            ['id' => '13', 'title' => 'Oxford Community', 'slug' => 'community', 'details' => '<p><strong>Oxford English Centre: A private-sector practical and concert model to advance sustainable development</strong></p>\r\n\r\n<p>Oxford English Centre-Gaza has committed itself towards sustainable development through offering quality education and life-changing learning experiences to Gaza youth. As a private sector institution working under the umbrella of the following <strong>SDGs</strong>: <strong>Goals 4, 5 and 8</strong>, we aim to further advance sustainable development in Gaza through launching our S<strong>DGs</strong>-oriented community.</p>\r\n\r\n<p><strong>Oxford Community</strong></p>\r\n\r\n<p>Oxford Community is a non-profit initiative by The Oxford English Centre to contribute to sustainable development in Gaza. It was launched in September 2018 targeting Palestinian youth through capacity building programmes, community service programmes and raising the awareness about <strong>SDGs</strong>.</p>\r\n\r\n<p><strong>Our Mission</strong></p>\r\n\r\n<p>To effectively contribute to sustainable development in Gaza through engaging and empowering youth</p>\r\n\r\n<p><strong>Our Objectives</strong></p>\r\n\r\n<ol>\r\n	<li>Raising awareness among our students&rsquo; network to make a significant impact on the <strong>SDGs</strong></li>\r\n	<li>Helping students understand and engage with the 2030 <strong>SDGs</strong></li>\r\n	<li>Offering capacity building programmes and dynamic learning environments</li>\r\n	<li>Creating a platform for <strong>SDGs</strong>-oriented community service groups made of volunteers</li>\r\n	<li>Working with local NGOs, governmental and private sector organisations to launch <strong>SDGs</strong>-informed initiatives</li>\r\n</ol>', 'image' => 'uploads/image/image_1563810369.png', 'banner' => '/uploads/photos/shares/5d3ee2e597dad.jpg', 'url' => null, 'tags' => 'Oxford Community,SDGs,Goals,gaza,ielts,oxford,test,community,sustainable,development', 'status' => '1', 'age' => null, 'level' => null, 'weeks' => null, 'hours' => null, 'mock' => null, 'duration' => null, 'class_size' => null, 'fees' => null, 'price' => null, 'start' => null, 'days' => null, 'time' => null, 'created_at' => '2017-08-15 15:45:27', 'updated_at' => '2019-07-29 23:16:08', 'deleted_at' => null, ],
            ['id' => '14', 'title' => 'Welcome To Oxford', 'slug' => 'intro', 'details' => '<p data-mce-style=\"text-align: justify;\">The Oxford English Centre has been delivering high quality English language tuition to students since its establishment in 2011 and has built a strong reputation as one of the most prestigious English language Centres in Gaza.</p>\r\n\r\n<p data-mce-style=\"text-align: justify;\">We make it our mission to welcome you into our family of staff, teachers and students. From the moment you first walk through our door we will do everything possible to make you feel at home, and ensure your course and your stay with us are&nbsp;smooth, fun, and productive.</p>', 'image' => 'uploads/image/image_1564416182.jpg', 'banner' => '/uploads/photos/shares/5d3ed325e2957.jpg', 'url' => 'https://www.youtube.com/watch?v=9slg-jDuqYM', 'tags' => 'oxford,english,centre,ielts,course,toefl,level', 'status' => '1', 'age' => null, 'level' => null, 'weeks' => null, 'hours' => null, 'mock' => null, 'duration' => null, 'class_size' => null, 'fees' => null, 'price' => null, 'start' => null, 'days' => null, 'time' => null, 'created_at' => '2017-08-15 15:45:27', 'updated_at' => '2019-07-30 03:03:02', 'deleted_at' => null, ],
            ['id' => '15', 'title' => 'Privacy Policy', 'slug' => 'privacy', 'details' => '<p><strong>Your privacy is important to us. It is oxford&#39;s policy to respect your privacy regarding any information we may collect from you across our website, <a href=\"http://new.oxford.ps\">http://oxford.ps</a>, and other sites we own and operate.</strong></p>\r\n\r\n<p>We only ask for personal information when we truly need it to provide a service to you. We collect it by fair and lawful means, with your knowledge and consent. We also let you know why we&rsquo;re collecting it and how it will be used.</p>\r\n\r\n<p>We only retain collected information for as long as necessary to provide you with your requested service. What data we store, we&rsquo;ll protect within commercially acceptable means to prevent loss and theft, as well as unauthorised access, disclosure, copying, use or modification.</p>\r\n\r\n<p>We don&rsquo;t share any personally identifying information publicly or with third-parties, except when required to by law.</p>\r\n\r\n<p>Our website may link to external sites that are not operated by us. Please be aware that we have no control over the content and practices of these sites, and cannot accept responsibility or liability for their respective privacy policies.</p>\r\n\r\n<p>You are free to refuse our request for your personal information, with the understanding that we may be unable to provide you with some of your desired services.</p>\r\n\r\n<p>Your continued use of our website will be regarded as acceptance of our practices around privacy and personal information. If you have any questions about how we handle user data and personal information, feel free to contact us.</p>\r\n\r\n<p>This policy is effective as of 23 July 2019.</p>\r\n\r\n<p>&nbsp;</p>', 'image' => 'image_1566297084.jpg', 'banner' => '/uploads/photos/shares/banner/5d5bcbed2478b.jpg', 'url' => null, 'tags' => 'oxford ,ielts,english,gaza', 'status' => '1', 'age' => null, 'level' => null, 'weeks' => null, 'hours' => null, 'mock' => null, 'duration' => null, 'class_size' => null, 'fees' => null, 'price' => null, 'start' => null, 'days' => null, 'time' => null, 'created_at' => '2017-08-15 15:45:27', 'updated_at' => '2019-08-20 21:34:18', 'deleted_at' => null, ],
            ['id' => '16', 'title' => 'Terms of Service', 'slug' => 'tos', 'details' => '<p><strong>Oxford was established by distinguished TESOL experts who are well-informed with broad knowledge in material design and selection with relevant academic and professional experience spanned over 10 years as researchers and Language Instructors. Oxford has a solid reputation in appointing distinguished A-List staff members who are all committed to the concept of creating a difference in the Palestinian educational life through transferring the cognition and expertise they gained from their studies in both the UK and the US. They are all inspiring figures, scholarships winners and leaders in their fields. Thus, we believe we can add value to the training by giving trainees models to follow and providing them with a great inspirational atmosphere.</strong></p>', 'image' => 'image_1563348770.jpg', 'banner' => '', 'url' => 'https://www.youtube.com/watch?v=9slg-jDuqYM', 'tags' => 'الرئيسية,صفحة,صفحة ثابتة,ثابتة', 'status' => '0', 'age' => null, 'level' => null, 'weeks' => null, 'hours' => null, 'mock' => null, 'duration' => null, 'class_size' => null, 'fees' => null, 'price' => null, 'start' => null, 'days' => null, 'time' => null, 'created_at' => '2017-08-15 15:45:27', 'updated_at' => '2019-08-20 21:42:04', 'deleted_at' => null, ],
